@prefix ns2: <http://www.w3.org/2003/06/sw-vocab-status/ns#> .
@prefix ns3: <http://www.cidoc-crm.org/cidoc-crm/> .
@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix schema: <https://schema.org/> .

<https://example.org/medal_ZappianGames_1870> rdf:type ns2:CACAO_0000081 ;
    ns3:P129i_is_subject_of <https://example.org/inscription_front> ;
    ns3:P138_represents <https://example.org/george_a_king_of_greeks> ;
    schema:description "Reproduction of a medal from the Zappian Games of 1870. Front view inscription 'ΓΕΩΡΓΙΟΣ Α! ΒΑΣΙΛΕΥΣ ΤΩΝ ΕΛΛΗΝΩΝ' - 'GEORGE A! KING OF THE GREEKS' and in the center has a representation of him. On the reverse side is depicted an olive wreath and is inscribed on the inside 'ΑΓΩΝΟΘΕΤΗΣ ΕΥΑΓΓΕΛΗΣ ΖΑΓΓΑΣ, ΟΛΥΜΠΙΑ ΑΘΗΝΗΣΙ ΑΩΟ΄ '(ΖΑΠΠΕΙΑ ΟΛΥΜΠΙΑ) - 'GAMES SETTER EVAGELIS ZAGAS, OLYMPIA ATHENS AΩO' (ZAPPEIA OLYMPIA)" .

<https://example.org/george_a_king_of_greeks> rdf:type ns3:E21_Person ;
    ns3:P1i_identifies <https://example.org/inscription_front> .

<https://example.org/inscription_front> rdf:type ns3:E41_Appellation ;
    rdfs:label "ΓΕΩΡΓΙΟΣ Α! ΒΑΣΙΛΕΥΣ ΤΩΝ ΕΛΛΗΝΩΝ - GEORGE A! KING OF THE GREEKS" .

<https://example.org/inscription_reverse> rdf:type ns3:E41_Appellation ;
    rdfs:label "ΑΓΩΝΟΘΕΤΗΣ ΕΥΑΓΓΕΛΗΣ ΖΑΓΓΑΣ, ΟΛΥΜΠΙΑ ΑΘΗΝΗΣΙ ΑΩΟ΄ (ΖΑΠΠΕΙΑ ΟΛΥΜΠΙΑ) - GAMES SETTER EVAGELIS ZAGAS, OLYMPIA ATHENS AΩO (ZAPPEIA OLYMPIA)" .

<https://example.org/zappian_games_1870> rdf:type ns2:CACAO_0000005 ;
    ns3:P129i_is_subject_of <https://example.org/inscription_reverse> .
